/* eslint-disable no-restricted-syntax, no-invalid-this, no-underscore-dangle */

'use strict';

// MODULES //

var MathJax = require( 'mathjax' );
var SRE = require( 'speech-rule-engine/cjs/common/system.js' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var replace = require( '@stdlib/string/base/replace' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var RE_DATA_ATTRIBUTES = /\sdata-[\w:-]+="[^"]*"/g;
var RE_ARIA_LEVEL_ATTRIBUTES = /\saria-level="[^"]*"/g;
var RE_EMPTY_GROUPS = /\s<g><\/g>/g;

var INIT = false;


// FUNCTIONS //

/**
* Returns MathJax options.
*
* @private
* @returns {Object} options
*/
function mOptions() {
	return {
		'loader': {
			'load': [
				'input/tex',                      // process TeX input
				'output/svg',                     // generate SVG output
				'adaptors/liteDOM'                // lightweight DOM for server use
			]
		},
		'options': {
			'compileError': onCompileError,       // handler for trapping compilation errors
			'typesetError': onTypesetError        // handler for trapping errors encountered during typesetting
		},
		'svg': {
			'fontCache': 'local'                  // make each SVG self-contained
		},
		'tex': {
			'formatError': onFormatError          // handler for trapping errors during parsing
		}
	};
}

/**
* Returns SRE options.
*
* @private
* @param {string} modality - modality
* @returns {Object} options
*/
function sOptions( modality ) {
	return {
		'locale': 'en',
		'domain': 'mathspeak',
		'style': 'default',
		'modality': modality,
		'markup': 'none'
	};
}

/**
* Callback invoked upon encountering a format error.
*
* ## Notes
*
* -   This catches TeX expressions which do not parse properly.
*
* @private
* @param {Object} jax - TeX input jax
* @param {Error} error - error object
* @throws {Error} unexpected error
*/
function onFormatError( jax, error ) {
	throw new Error( format( 'invalid argument. Must provide a valid TeX or LaTeX string. %s. Value: `\'%s\'`.', error.message, jax.latex ) );
}

/**
* Callback invoked upon encountering a compile error.
*
* ## Notes
*
* -   This catches TeX expressions which do not parse properly.
*
* @private
* @param {Object} document - math document object
* @param {Object} math - math item object
* @param {Error} error - error object
* @throws {Error} unexpected error
*/
function onCompileError( document, math, error ) {
	throw new Error( format( 'invalid argument. Must provide a valid TeX or LaTeX string. %s. Value: `\'%s\'`.', error.message, math.math ) );
}

/**
* Callback invoked upon encountering a typeset error.
*
* ## Notes
*
* -   This catches TeX expressions which do not parse properly.
*
* @private
* @param {Object} document - math document object
* @param {Object} math - math item object
* @param {Error} error - error object
* @throws {Error} unexpected error
*/
function onTypesetError( document, math, error ) {
	throw new Error( format( 'invalid argument. Must provide a valid TeX or LaTeX string. %s. Value: `\'%s\'`.', error.message, math.math ) );
}


// MAIN //

/**
* Wrapper around MathJax.
*
* @private
* @constructor
* @returns {Wrapper} MathJax wrapper
*/
function MathJaxWrapper() {
	if ( !( this instanceof MathJaxWrapper ) ) {
		return new MathJaxWrapper();
	}
	return this;
}

/**
* Converts a "raw" MML node to a SVG string.
*
* @private
* @name _serialize2svg
* @memberof MathJaxWrapper.prototype
* @type {Function}
* @param {Object} node - raw node
* @returns {string} SVG string
*/
setReadOnly( MathJaxWrapper.prototype, '_serialize2svg', function serialize2svg( node ) {
	var adaptor;
	var braille;
	var speech;
	var svg;
	var str;

	adaptor = MathJax.startup.adaptor;
	speech = adaptor.getAttribute( node, 'data-semantic-speech-none' ) || '';
	braille = adaptor.getAttribute( node, 'data-semantic-braille' ) || '';

	svg = adaptor.tags( node, 'svg' )[ 0 ];
	if ( speech ) {
		adaptor.setAttribute( svg, 'aria-label', speech );
	}
	if ( braille ) {
		adaptor.setAttribute( svg, 'aria-braillelabel', braille );
	}
	str = adaptor.serializeXML( svg );

	str = replace( str, RE_DATA_ATTRIBUTES, '' );
	str = replace( str, RE_ARIA_LEVEL_ATTRIBUTES, '' );
	str = replace( str, RE_EMPTY_GROUPS, '' );

	return str;
});

/**
* Initialize the SRE engine.
*
* @private
* @name _initSpeechEngine
* @memberof MathJaxWrapper.prototype
* @type {Function}
* @param {string} modality - modality
* @param {Callback} clbk - callback to invoke upon completion
*/
setReadOnly( MathJaxWrapper.prototype, '_initSpeechEngine', function initSpeechEngine( modality, clbk ) {
	var p = SRE.setupEngine( sOptions( modality ) );
	p.then( onSetup ).catch( onError );

	/**
	* Callback invoked upon setup.
	*
	* @private
	*/
	function onSetup() {
		var p = SRE.engineReady();
		p.then( onReady ).catch( onError );
	}

	/**
	* Callback invoked once the SRE engine is ready.
	*
	* @private
	*/
	function onReady() {
		clbk();
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	*/
	function onError( error ) {
		clbk( error );
	}
});

/**
* Converts a TeX string to MML.
*
* @name _tex2mml
* @memberof MathJaxWrapper.prototype
* @type {Function}
* @param {string} str - TeX string
* @param {Options} opts - options
* @param {Callback} clbk - callback to invoke upon completion
*/
setReadOnly( MathJaxWrapper.prototype, '_tex2mml', function tex2mml( str, opts, clbk ) {
	var p = MathJax.tex2mmlPromise( str, opts );
	p.then( onSVG ).catch( onError );

	/**
	* Callback invoked upon converting a TeX string to an SVG.
	*
	* @private
	* @param {Object} node - output
	*/
	function onSVG( node ) {
		clbk( null, node );
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	* @returns {void}
	*/
	function onError( error ) {
		clbk( error );
	}
});

/**
* Initializes MathJax.
*
* @private
* @name _init
* @memberof MathJaxWrapper.prototype
* @type {Function}
* @param {Callback} clbk - callback to invoke after completing initialization
* @returns {void}
*/
setReadOnly( MathJaxWrapper.prototype, '_init', function onInit( clbk ) {
	var p;

	if ( INIT ) {
		return clbk();
	}
	p = MathJax.init( mOptions() );
	p.then( onInit ).catch( onError );

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	* @returns {void}
	*/
	function onError( error ) {
		clbk( error );
	}

	/**
	* Callback invoked upon successfully initializing MathJax.
	*
	* @private
	*/
	function onInit() {
		INIT = true;
		clbk();
	}
});

/**
* Converts a TeX string to an SVG.
*
* @name tex2svg
* @memberof MathJaxWrapper.prototype
* @type {Function}
* @param {string} str - TeX string
* @param {Options} opts - options
* @param {Callback} clbk - callback to invoke upon completion
*/
setReadOnly( MathJaxWrapper.prototype, 'tex2svg', function tex2svg( str, opts, clbk ) {
	var self;
	var svg;
	var mml;

	self = this;
	if ( !INIT ) {
		this._init( convert );
		return;
	}
	convert();

	/**
	* Converts a TeX string to an SVG.
	*
	* @private
	* @param {Error} [error] - error object
	* @returns {void}
	*/
	function convert( error ) {
		var p;
		if ( error ) {
			return clbk( error );
		}
		p = MathJax.tex2svgPromise( str, opts );
		p.then( onSVG ).catch( onError );
	}

	/**
	* Callback invoked upon converting a TeX string to an SVG.
	*
	* @private
	* @param {Object} node - output
	*/
	function onSVG( node ) {
		svg = MathJax.startup.adaptor.tags( node, 'svg' )[ 0 ];
		self._tex2mml( str, opts, onMML );
	}

	/**
	* Callback invoked upon converting a TeX string to MML.
	*
	* @private
	* @param {(Error|null)} error - error object
	* @param {Object} node - output
	* @returns {void}
	*/
	function onMML( error, node ) {
		if ( error ) {
			return clbk( error );
		}
		mml = node;
		self._initSpeechEngine( 'speech', onInitSpeech );
	}

	/**
	* Callback invoked upon initializing a speech engine.
	*
	* @private
	*/
	function onInitSpeech() {
		var str = SRE.toSpeech( mml );
		MathJax.startup.adaptor.setAttribute( svg, 'aria-label', str );
		self._initSpeechEngine( 'braille', onInitBraille );
	}

	/**
	* Callback invoked upon initializing a braille engine.
	*
	* @private
	*/
	function onInitBraille() {
		// var str = SRE.toSpeech( mml ); // FIXME: uncomment once we can generate Braille

		// FIXME: generating Braille seems to be broken in the upstream library. Even basic examples fail to render properly. We should revisit once v5.0 is no longer in alpha/beta mode.

		// MathJax.startup.adaptor.setAttribute( svg, 'aria-braillelabel', str ); // FIXME: uncomment once we can generate Braille
		clbk( null, self._serialize2svg( svg ) );
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	* @returns {void}
	*/
	function onError( error ) {
		clbk( error );
	}
});


// EXPORTS //

module.exports = MathJaxWrapper;
